const formatCell=(k:string,v:any)=>{
 if(v===null||v===undefined||v==='')return '—';
 if(k.endsWith('_cents'))return money(v);
 if(k==='enabled'||k==='archived')return v?'Sim':'Não';
 if(k.endsWith('_on')||k==='occurred_on'||k==='purchased_on'||k==='traded_on'||k==='paid_on')return String(v).slice(0,10).split('-').reverse().join('/');
 if(k==='kind'){const d:Record<string,string>={income:'Receita',expense:'Despesa',transfer:'Transferência',checking:'Corrente',savings:'Poupança',cash:'Dinheiro',digital:'Digital',buy:'Compra',sell:'Venda',dividend:'Rendimento',fee:'Taxa',receivable:'A receber',payable:'A pagar'};return d[String(v)]||String(v);}
 if(k==='direction')return v==='receivable'?'A receber':'A pagar';
 if(k==='status'){const d:Record<string,string>={open:'Aberto',paid:'Pago',draft:'Rascunho',active:'Ativo',paused:'Pausado',cancelled:'Cancelado',void:'Cancelado'};return d[String(v)]||String(v);}
 if(typeof v==='object')return JSON.stringify(v);
 return String(v);
};

function Metric({label,value,change,icon:Icon=Wallet,tone='purple',note}:{label:string,value:string,change?:string,icon?:any,tone?:string,note?:string}){
 return <div className="metric-card"><div className="metric-head"><span>{label}</span><span className={`metric-icon ${tone}`}><Icon size={17}/></span></div><div className="metric-value">{value}</div>{change&&<div className="metric-delta">{change}</div>}{note&&<div className="metric-note">{note}</div>}</div>;
}
function Panel({title,subtitle,children,action}:{title:string,subtitle?:string,children:React.ReactNode,action?:React.ReactNode}){
 return <section className="panel"><header className="panel-header"><div><h3>{title}</h3>{subtitle&&<p>{subtitle}</p>}</div>{action}</header>{children}</section>;
}
function ChartEmpty(){return <div className="chart-empty"><BarChart3 size={26}/><span>Dados insuficientes para este gráfico</span><small>Registre movimentações para iniciar a análise.</small></div>;}
const tooltipProps={contentStyle:{background:'#1b2140',border:'1px solid #384161',borderRadius:12,color:'#fff'},labelStyle:{color:'#b8c3e8'},formatter:(v:any)=>money(v)};
function CashFlowChart({data,mode='area'}:{data:any[],mode?:'area'|'bar'|'line'}){
 if(!data?.length)return <ChartEmpty/>;
 return <div className="chart"><ResponsiveContainer width="100%" height="100%">{mode==='bar'?<BarChart data={data}><CartesianGrid vertical={false} stroke="var(--chart-grid)"/><XAxis dataKey="month" tick={{fontSize:11,fill:"var(--muted)"}}/><YAxis tickFormatter={compact} tick={{fontSize:11,fill:"var(--muted)"}}/><Tooltip {...tooltipProps}/><Legend wrapperStyle={{color:"var(--muted)"}}/><Bar dataKey="income" name="Receitas" fill="#49baa7" radius={[5,5,0,0]}/><Bar dataKey="expenses" name="Despesas" fill="#ec8e95" radius={[5,5,0,0]}/></BarChart>:mode==='line'?<LineChart data={data}><CartesianGrid vertical={false} stroke="var(--chart-grid)"/><XAxis dataKey="month" tick={{fontSize:11,fill:"var(--muted)"}}/><YAxis tickFormatter={compact} tick={{fontSize:11,fill:"var(--muted)"}}/><Tooltip {...tooltipProps}/><Legend wrapperStyle={{color:"var(--muted)"}}/><Line type="monotone" dataKey="income" name="Receitas" stroke="#49baa7" strokeWidth={3}/><Line type="monotone" dataKey="expenses" name="Despesas" stroke="#ee8999" strokeWidth={3}/></LineChart>:<AreaChart data={data}><defs><linearGradient id="grA" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#7B6CEE" stopOpacity={.3}/><stop offset="100%" stopColor="#7B6CEE" stopOpacity={0}/></linearGradient></defs><CartesianGrid vertical={false} stroke="var(--chart-grid)"/><XAxis dataKey="month" tick={{fontSize:11,fill:"var(--muted)"}}/><YAxis tickFormatter={compact} tick={{fontSize:11,fill:"var(--muted)"}}/><Tooltip {...tooltipProps}/><Area type="monotone" name="Resultado" dataKey="result" stroke="#7769e9" fill="url(#grA)" strokeWidth={3}/></AreaChart>}</ResponsiveContainer></div>;
}
function CategoryChart({data,centerLabel="Gastos do mês"}:{data:any[],centerLabel?:string}){
 if(!data?.length)return <ChartEmpty/>;
 return <div className="category-chart"><div className="donut"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={data} dataKey="value" innerRadius="69%" outerRadius="91%" paddingAngle={2} stroke="none">{data.map((c,i)=><Cell key={i} fill={c.color||genColor[i%genColor.length]}/>)}</Pie><Tooltip {...tooltipProps}/></PieChart></ResponsiveContainer><div className="donut-center"><small>{centerLabel}</small><b>{money(data.reduce((a,b)=>a+b.value,0))}</b></div></div><div className="legend-list">{data.slice(0,7).map((d,i)=><div className="legend-row" key={i}><span className="color-dot" style={{background:d.color||genColor[i%7]}}/><span>{d.name}</span><b>{money(d.value)}</b></div>)}</div></div>;
}
function HorizontalBars({data}:{data:{name:string,value:number,color?:string}[]}){
 if(!data.length)return <ChartEmpty/>;const max=Math.max(...data.map(x=>Math.max(x.value,0)),1);
 return <div className="hbars">{data.slice(0,12).map((x,i)=><div className="hbar" key={i}><div className="hbar-label"><span>{x.name}</span><b>{money(x.value)}</b></div><div className="hbar-track"><div className="hbar-fill" style={{width:`${Math.max(0,x.value)/max*100}%`,background:x.color||genColor[i%genColor.length]}}/></div></div>)}</div>;
}
function Empty({action}:{action?:()=>void}){return <div className="empty-state"><span className="empty-art"><Layers size={34}/></span><h3>Seu espaço está pronto para receber dados</h3><p>Adicione o primeiro registro para começar a acompanhar indicadores, comparações e oportunidades.</p>{action&&<button className="btn btn-primary" onClick={action}><Plus size={16}/> Adicionar registro</button>}</div>;}

export default function FinanceApp(){
 const [status,setStatus]=useState<'loading'|'setup'|'login'|'ready'|'unavailable'>('loading');
 const [authError,setAuthError]=useState(''),[startupError,setStartupError]=useState(''),[me,setMe]=useState<AnyRow|null>(null);
 const [workspace,setWorkspace]=useState(''),[section,setSection]=useState('overview'),[tab,setTab]=useState(''),[report,setReport]=useState('executive');
 const [overview,setOverview]=useState<AnyRow|null>(null),[rows,setRows]=useState<AnyRow[]>([]),[busy,setBusy]=useState(false),[refresh,setRefresh]=useState(0),[loadError,setLoadError]=useState('');
 const [modal,setModal]=useState<{entity:string,row?:AnyRow}|null>(null),[modalError,setModalError]=useState(''),[toast,setToast]=useState(''),[search,setSearch]=useState('');
 const [dark,setDark]=useState(false),[navOpen,setNavOpen]=useState(false),[offset,setOffset]=useState(0);
 useEffect(()=>{try{setDark(window.localStorage.getItem('finance-hub-theme')==='dark')}catch{}},[]);
 const toggleAppearance=()=>{const next=!dark;setDark(next);try{window.localStorage.setItem('finance-hub-theme',next?'dark':'light')}catch{}};
 const currentWorkspace=me?.workspaces?.find((x:AnyRow)=>x.id===workspace);
 const isViewer=currentWorkspace?.role==='viewer';
 const currentEntity=tab||tabsBySection[section]?.[0]?.id||'';
 const send=async(url:string,body?:any,method?:string)=>{
  const r=await fetch(url,{method:method||(body?'POST':'GET'),headers:body?{'Content-Type':'application/json','X-Workspace':workspace}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});
  const v=await r.json().catch(()=>({error:'Resposta inválida.'}));if(!r.ok)throw Object.assign(Error(v.error||`Erro ${r.status}`),{httpStatus:r.status});return v;
 };
 const reloadMe=async()=>{const value=await send('/api/me');setMe(value);if(!workspace||!value.workspaces.find((x:AnyRow)=>x.id===workspace))setWorkspace(value.workspaces[0]?.id||'');setStatus('ready');};
 useEffect(()=>{(async()=>{try{const config=await send('/api/setup-status');if(!config.configured){setStatus('setup');return;}await reloadMe();}catch(e){if((e as Error&{httpStatus?:number}).httpStatus===401){setStatus('login');return;}setStartupError((e as Error).message);setStatus('unavailable');}})();},[]);
 useEffect(()=>{if(!workspace||status!=='ready')return;let alive=true;setBusy(true);setLoadError('');
 // Uma falha no analytics NÃO pode bloquear os cadastros e lançamentos.
 const loadOverview=send(`/api/overview?workspace=${encodeURIComponent(workspace)}`);
 const loadRows=currentEntity?send(`/api/data?workspace=${encodeURIComponent(workspace)}&entity=${encodeURIComponent(currentEntity)}&offset=${offset}`):Promise.resolve({rows:[]});
 Promise.allSettled([loadOverview,loadRows]).then(([a,b])=>{if(!alive)return;
  const errors:string[]=[];
  if(a.status==='fulfilled')setOverview(a.value);else{setOverview(null);errors.push(`Painel analítico: ${(a.reason as Error).message}`);}
  if(b.status==='fulfilled')setRows(b.value.rows||[]);else{setRows([]);errors.push(`Consulta de registros: ${(b.reason as Error).message}`);}
  setLoadError(errors.join(' | '));
 }).finally(()=>{if(alive)setBusy(false);});return()=>{alive=false;};},[workspace,section,tab,refresh,offset,status]);
 const notify=(message:string)=>{setToast(message);window.setTimeout(()=>setToast(''),4500);};
 const navigate=(s:string)=>{setSection(s);setTab(tabsBySection[s]?.[0]?.id||'');setOffset(0);setSearch('');setNavOpen(false);};
 const authenticate=async(values:Record<string,string>)=>{try{setAuthError('');await send(status==='setup'?'/api/setup':'/api/login',status==='setup'?{code:values.code,name:values.name,email:values.email,password:values.password}:values);
 await reloadMe();}catch(e){setAuthError((e as Error).message);}};
 const logout=async()=>{await send('/api/logout',{});setMe(null);setStatus('login');setWorkspace('');};
 const open=(entity:string,row?:AnyRow)=>{setModal({entity,row});setModalError('');};
 const refreshAll=()=>setRefresh(n=>n+1);
 const mutate=async(entity:string,data:AnyRow,row?:AnyRow)=>{
  if(entity==='workspaces'){await send('/api/workspaces',data);await reloadMe();}
  else if(entity==='members'){await send('/api/member?workspace='+workspace,{action:'create',...data});}
  else {
   const endpoints:Record<string,string>={transactions:'/api/transaction',card_purchases:'/api/card/purchase',card_payments:'/api/card/payment',trades:'/api/trade',asset_prices:'/api/price',invoice_settle:'/api/invoice/settle',debt_payments:'/api/debt/payment',import:'/api/import'};
   if(endpoints[entity])await send(endpoints[entity]+'?workspace='+workspace,data);
   else await send('/api/manage?workspace='+workspace,{entity,action:row?'update':'create',id:row?.id,data});
  }
  setModal(null);refreshAll();notify(`${enName[entity]||'Registro'} salvo com sucesso.`);
 };
 const doAction=async(endpoint:string,id:string,confirmText:string)=>{
  if(!window.confirm(confirmText))return;
  try{await send(endpoint+'?workspace='+workspace,{id});refreshAll();notify('Operação registrada com sucesso.');}catch(e){notify((e as Error).message);}
 };
 const exportRows=()=>{
  const visible=rows.map(r=>Object.fromEntries(Object.entries(r).filter(([k])=>!omitCols.has(k)&&!k.endsWith('_enc'))));
  const columns=[...new Set(visible.flatMap(r=>Object.keys(r)))];
  const escape=(v:any)=>{const s=String(v??'');const guarded=/^[=+@\-\t\r]/.test(s)?`'${s}`:s;return '"'+guarded.replace(/"/g,'""')+'"';};
  const text=[columns.map(escape).join(','),...visible.map(r=>columns.map(k=>escape(r[k])).join(','))].join('\r\n');
  const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/csv;charset=utf-8'}));a.download=`finance-hub-${currentEntity}-${today()}.csv`;a.click();URL.revokeObjectURL(a.href);
 };
 const filteredRows=useMemo(()=>rows.filter(x=>Object.entries(x).some(([key,value])=>!omitCols.has(key)&&String(value??'').toLowerCase().includes(search.toLowerCase()))),[rows,search]);
 const allFields:Record<string,AnyRow[]>={accounts:overview?.accounts||[],categories:overview?.categories||[],cards:overview?.cards||[],assets:overview?.positions||[],contacts:section==='business'&&currentEntity==='contacts'?rows:[],debts:overview?.debts||[],invoices:overview?.invoices||[]};
 // Reference selectors must work even when the referenced table is not the current tab.
 const [refs,setRefs]=useState<Record<string,AnyRow[]>>({});
 useEffect(()=>{if(!workspace||!modal)return;let active=true;
  Promise.all(['accounts','cards','assets','contacts','debts','invoices'].map(async entity=>{try{return [entity,(await send(`/api/data?workspace=${workspace}&entity=${entity}`)).rows] as const;}catch{return [entity,[]] as const;}})).then(list=>{if(active)setRefs(Object.fromEntries(list));});return()=>{active=false;};
 },[workspace,modal?.entity]);
 if(status==='loading')return <div className="loading-cover"><div className="logo-square"><Layers size={28}/></div><div className="loader"/><p>Preparando seu espaço financeiro...</p></div>;
 if(status==='unavailable')return <div className="auth-page"><div className="auth-box"><h1>Serviço indisponível</h1><p>A conexão inicial com o banco ou a API falhou. Verifique o diagnóstico no PowerShell.</p><div className="auth-error">{startupError}</div><button className="btn btn-primary" onClick={()=>window.location.reload()}>Tentar novamente</button><p>Comando: docker compose logs --tail=80 web migrate db</p></div></div>;
 if(status==='login'||status==='setup')return <AuthScreen mode={status} error={authError} onSubmit={authenticate}/>;
 const s=overview?.summary||{};
 return <div className={`app-shell ${dark?'dark':''}`}>
  <div className={`sidebar-mask ${navOpen?'visible':''}`} onClick={()=>setNavOpen(false)}/>
  <aside className={`sidebar ${navOpen?'mobile-visible':''}`}>
   <div className="brand"><div className="brand-icon"><Layers size={23} strokeWidth={2.4}/></div><div><strong>finance<span>hub</span></strong><small>PERSONAL WEALTH OS</small></div><button className="mobile-close icon-btn" onClick={()=>setNavOpen(false)}><X size={18}/></button></div>
   <div className="sidebar-workspace"><div className="workspace-avatar">{currentWorkspace?.kind==='business'?<BriefcaseBusiness size={18}/>:<Wallet size={18}/>}</div><div className="workspace-meta"><b>{currentWorkspace?.name||'Seu espaço'}</b><small>{currentWorkspace?.kind==='business'?'Empresarial':currentWorkspace?.kind==='family'?'Familiar':'Pessoal'} · BRL</small></div><ChevronDown size={15}/></div>
   <nav className="sidebar-nav">{navigation.map((n,i)=>{const Icon=n.icon;return <Fragment key={n.id}>{(i===0||n.group!==navigation[i-1].group)&&<div className="nav-group">{n.group}</div>}<button className={`nav-item ${section===n.id?'selected':''}`} onClick={()=>navigate(n.id)}><Icon size={19} strokeWidth={1.85}/><span>{n.name}</span>{section===n.id&&<span className="nav-selected-dot"/>}</button></Fragment>;})}</nav>
   <div className="sidebar-bottom"><div className="secure-pill"><ShieldCheck size={18}/><div><b>Ambiente privado</b><small>Dados no seu dispositivo</small></div></div><p>Finance Hub 1.3.4 · Self-hosted</p></div>
  </aside>
  <div className="main-shell">
   <header className="topbar"><div className="top-left"><button className="icon-btn burger" onClick={()=>setNavOpen(true)}><Menu size={22}/></button><span className="breadcrumb">Workspace</span><ChevronRight size={15}/><b>{navigation.find(n=>n.id===section)?.name||'Visão geral'}</b></div><div className="top-actions"><span className="local-badge"><span/> LOCAL · SEGURO</span><button className="icon-btn" title="Alternar aparência" onClick={toggleAppearance}>{dark?<Sun size={19}/>:<Moon size={19}/>}</button><button className="user-chip" title="Sair da sessão" onClick={logout}><span>{String(me?.user?.name||'U').slice(0,1).toUpperCase()}</span><div><b>{me?.user?.name}</b><small>Encerrar sessão</small></div><LogOut size={16}/></button></div></header>
   <main className="content">
    <div className="page-top"><div><div className="eyebrow"><span className="eyebrow-dot"/> PAINEL FINANCEIRO INTELIGENTE</div><h1>{section==='overview'?'Seu dinheiro, com clareza.':navigation.find(n=>n.id===section)?.name}</h1><p>{section==='overview'?'Uma visão conectada de finanças, patrimônio e oportunidades.':section==='reports'?'Explore indicadores, comparações, tendências e análises explicáveis.':`Organize e analise ${navigation.find(n=>n.id===section)?.name.toLowerCase()} com rastreabilidade.`}</p></div><div className="page-actions"><select className="workspace-select" value={workspace} onChange={e=>{setWorkspace(e.target.value);setOffset(0)}}>{me?.workspaces?.map((w:AnyRow)=><option key={w.id} value={w.id}>{w.name} · {w.kind}</option>)}</select><button className="btn btn-secondary" title="Criar espaço pessoal, familiar ou empresarial" onClick={()=>open('workspaces')}><Plus size={16}/> Espaço</button></div></div>
    {loadError&&<div role="alert" className="notice warning"><AlertTriangle size={18}/><span>Não foi possível carregar parte dos dados: {loadError}</span><button className="btn btn-secondary" onClick={refreshAll}>Tentar novamente</button></div>}
    {(section==='overview'||section==='reports')&&!overview&&busy&&<div className="loading-inline">Carregando indicadores financeiros...</div>}
    {(section==='overview'||section==='reports')&&!overview&&!busy&&!loadError&&<Empty action={()=>navigate('accounts')}/>}
    {(section==='overview'||section==='reports')&&overview&&<>
      {section==='reports'&&<div className="report-tabs">{reports.map(x=><button key={x.id} className={report===x.id?'active':''} onClick={()=>setReport(x.id)}>{x.label}</button>)}</div>}
      <Dashboard data={overview} report={section==='overview'?'executive':report} onNavigate={navigate} onAdd={()=>!isViewer&&open('transactions')}/>
    </>}
    {tabsBySection[section]&&<>
      {tabsBySection[section].length>1&&<div className="tabs">{tabsBySection[section].map(x=><button key={x.id} className={currentEntity===x.id?'active':''} onClick={()=>{setTab(x.id);setOffset(0);setSearch('')}}>{x.label}</button>)}</div>}
      {section==='investments'&&overview&&<div className="mini-metrics"><Metric label="Valor da carteira" value={money(s.invested)} icon={TrendingUp}/><Metric label="Posições" value={String(overview.positions?.filter((p:AnyRow)=>p.quantity>0).length||0)} icon={Layers}/><Metric label="Resultado não realizado" value={money(overview.positions?.reduce((a:number,p:AnyRow)=>a+p.unrealized,0))} icon={BarChart3}/></div>}
      {section==='business'&&overview&&<div className="mini-metrics"><Metric label="A receber" value={money(s.receivables)} icon={ArrowDownLeft}/><Metric label="A pagar" value={money(s.payables)} icon={ArrowUpRight}/><Metric label="Pipeline ponderado" value={money(s.weightedPipeline)} icon={BriefcaseBusiness}/></div>}
      <section className="panel list-panel"><div className="list-head"><div><h3>{tabsBySection[section].find(x=>x.id===currentEntity)?.label}</h3><p>Registros persistidos no PostgreSQL · {rows.length} nesta página</p></div><div className="list-actions"><button className="btn btn-ghost" title="Exportar CSV" onClick={exportRows}><Download size={17}/><span>Exportar</span></button>{!isViewer&&currentEntity==='transactions'&&<button className="btn btn-secondary" onClick={()=>open('import')}><FileSpreadsheet size={16}/> Importar CSV</button>}{!isViewer&&currentEntity==='invoices'&&<button className="btn btn-secondary" onClick={()=>open('invoice_settle')}><Check size={16}/> Quitar</button>}{!isViewer&&currentEntity==='debts'&&<button className="btn btn-secondary" onClick={()=>open('debt_payments')}><Check size={16}/> Amortizar</button>}{!isViewer&&currentEntity==='card_purchases'&&<button className="btn btn-secondary" onClick={()=>open('card_payments')}><Check size={16}/> Pagar fatura</button>}{!isViewer&&currentEntity==='assets'&&<button className="btn btn-secondary" onClick={()=>open('trades')}><TrendingUp size={16}/> Operação</button>}{!isViewer&&forms[currentEntity]&&<button className="btn btn-primary" onClick={()=>open(currentEntity)}><Plus size={17}/> Novo registro</button>}</div></div>
        <div className="table-toolbar"><div className="search-box"><Search size={17}/><input placeholder="Pesquisar registros visíveis..." value={search} onChange={e=>setSearch(e.target.value)}/>{search&&<button onClick={()=>setSearch('')}><X size={14}/></button>}</div><span className="table-hint"><Filter size={15}/> Pesquisa local · {filteredRows.length} registros</span></div>
        <div className="table-scroll">{busy&&!rows.length?<div className="loading-inline">Carregando dados...</div>:filteredRows.length?<table><thead><tr>{Object.keys(filteredRows[0]).filter(k=>!omitCols.has(k)&&!k.endsWith('_enc')&&k!=='source'&&k!=='fingerprint').slice(0,10).map(k=><th key={k}>{keyLabels[k]||k.replace(/_/g,' ')}</th>)}<th>Ações</th></tr></thead><tbody>{filteredRows.map((row,i)=><tr key={row.id||i}>{Object.keys(filteredRows[0]).filter(k=>!omitCols.has(k)&&!k.endsWith('_enc')&&k!=='source'&&k!=='fingerprint').slice(0,10).map(k=><td key={k}><span className={k==='status'||k==='kind'?'cell-label':''}>{formatCell(k,row[k])}</span></td>)}<td><div className="row-actions">{!isViewer&&forms[currentEntity]&&!['transactions','card_purchases','trades','asset_prices','card_payments','debt_payments','members'].includes(currentEntity)&&<button title="Editar" className="tiny-action" onClick={()=>open(currentEntity,row)}><Settings2 size={15}/></button>}{!isViewer&&currentEntity==='transactions'&&!row.voided_at&&<button title="Estornar" className="tiny-action danger" onClick={()=>doAction('/api/transaction/void',row.id,'Estornar esta transação? Uma entrada reversa será registrada no histórico.') }><ArrowLeftRight size={15}/></button>}{!isViewer&&currentEntity==='card_purchases'&&!row.voided_at&&<button title="Cancelar compra" className="tiny-action danger" onClick={()=>doAction('/api/card/void',row.id,'Cancelar a compra? Os compromissos de parcelas serão desconsiderados. Verifique pagamentos já efetuados.') }><X size={15}/></button>}{!isViewer&&currentEntity==='invoices'&&row.status==='open'&&<button className="tiny-action" title="Quitar" onClick={()=>open('invoice_settle',{id:row.id})}><Check size={15}/></button>}{!isViewer&&['budgets','goals','holdings','subscriptions','opportunities','automation_rules','schedules'].includes(currentEntity)&&<button title="Excluir" className="tiny-action danger" onClick={async()=>{if(!confirm('Excluir o registro?'))return;try{await send('/api/manage?workspace='+workspace,{entity:currentEntity,action:'delete',id:row.id});refreshAll();notify('Registro excluído.');}catch(e){notify((e as Error).message);}}}><Trash2 size={15}/></button>}</div></td></tr>)}</tbody></table>:<Empty action={!isViewer&&forms[currentEntity]?()=>open(currentEntity):undefined}/>}</div>
        <div className="table-footer"><span>{offset+1}–{offset+filteredRows.length} · máximo de 300 por página</span><div><button disabled={!offset} onClick={()=>setOffset(x=>Math.max(0,x-300))} className="icon-btn"><ChevronLeft size={17}/></button><button disabled={rows.length<300} onClick={()=>setOffset(x=>x+300)} className="icon-btn"><ChevronRight size={17}/></button></div></div>
      </section>
      {section==='automation'&&<div className="notice"><Bot size={20}/><span><b>Execução controlada:</b> regras de categorização atuam nos novos lançamentos; lançamentos programados só são processados quando explicitamente habilitados.</span></div>}
      {section==='settings'&&<div className="notice"><ShieldCheck size={20}/><span>Criptografia de campos AES-256-GCM, sessões protegidas, controle de acesso por espaço e auditoria. Configure BitLocker no Windows para cifrar também os arquivos do banco e seus backups.</span></div>}
    </>}
   </main>
  </div>
  {modal&&<DataModal key={`${modal.entity}-${modal.row?.id||'new'}`} entity={modal.entity} row={modal.row} fields={forms[modal.entity]||[]} references={{...allFields,...refs}} categories={overview?.categories||[]} onClose={()=>setModal(null)} onSave={async data=>{setModalError('');try{await mutate(modal.entity,data,modal.row);}catch(e){setModalError((e as Error).message);}}} error={modalError}/>}
  {toast&&<div className="toast"><CheckCircle2 size={18}/>{toast}<button onClick={()=>setToast('')}><X size={14}/></button></div>}
 </div>;
}

function Dashboard({data:d,report,onNavigate,onAdd}:{data:AnyRow,report:string,onNavigate:(s:string)=>void,onAdd:()=>void}){
 const s=d.summary,months=d.monthly||[],last=months.slice(-12),current=last[last.length-1]||{},prior=last[last.length-2]||{},spent=d.byCategory||[],positions=d.positions||[],cards=d.cards||[],goals=d.goals||[],debts=d.debts||[];
 const trend=(newVal:number,oldVal:number)=>oldVal?`${newVal>=oldVal?'+':''}${pct(((newVal-oldVal)/Math.abs(oldVal))*100)} vs. período anterior`:'Sem base histórica comparável';
 const forecast=Array.from({length:6},(_,i)=>{const hist=months.slice(-Math.min(6,months.length));const avgIncome=hist.reduce((a:number,x:AnyRow)=>a+x.income,0)/(hist.length||1),avgExpense=hist.reduce((a:number,x:AnyRow)=>a+x.expenses,0)/(hist.length||1);
 const date=new Date();date.setDate(1);date.setMonth(date.getMonth()+i+1);
 return {month:`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`,income:Math.round(avgIncome),expenses:Math.round(avgExpense),result:Math.round(avgIncome-avgExpense)};});
 const future=[...last.slice(-3),...forecast];
 const monthlyCard=(m:AnyRow)=><div className="list-simple"><div><span>Compras acumuladas</span><b>{money(Number(m.purchases_cents))}</b></div><div><span>Pagamentos registrados</span><b>{money(Number(m.paid_cents))}</b></div><div><span>Saldo pendente</span><b>{money(Number(m.purchases_cents)-Number(m.paid_cents))}</b></div><div><span>Limite disponível estimado</span><b>{money(Math.max(0,Number(m.limit_cents)-(Number(m.purchases_cents)-Number(m.paid_cents))))}</b></div></div>;
 const Summary=<div className="metrics-grid"><Metric label="Patrimônio líquido" value={money(s.netWorth)} icon={Landmark} change="Consolidado · ativos − passivos"/><Metric label="Disponível em contas" value={money(s.cash)} icon={Wallet} tone="green" change={`${d.accounts?.length||0} contas ativas`}/><Metric label="Receitas do mês" value={money(s.monthlyIncome)} icon={ArrowDownLeft} tone="blue" change={trend(s.monthlyIncome,prior.income)}/><Metric label="Despesas do mês" value={money(s.monthlyExpense)} icon={ArrowUpRight} tone="orange" change={trend(s.monthlyExpense,prior.expenses)}/></div>;
 const insightList=<div className="insight-list">{(d.insights||[]).map((a:AnyRow,i:number)=><button className={`insight ${a.type}`} key={i} onClick={()=>onNavigate(a.section)}><span className="insight-icon">{a.type==='risk'?<AlertTriangle size={19}/>:a.type==='opportunity'?<Sparkles size={19}/>:<Activity size={19}/>}</span><span><b>{a.title}</b><small>{a.detail}</small></span><ChevronRight size={16}/></button>)}{!d.insights?.length&&<p className="muted-padding">Nenhum alerta identificado com os dados disponíveis.</p>}</div>;
 const allocation=positions.filter((p:AnyRow)=>p.market>0).map((p:AnyRow,i:number)=>({name:p.symbol||p.asset_name,value:p.market,color:genColor[i%7]}));
 const financialStack=[{name:'Dinheiro',value:Math.max(0,s.cash),color:'#5DAEAA'},{name:'Investimentos',value:s.invested,color:'#7B6EEE'},{name:'Bens',value:s.tangible,color:'#E6AE72'},{name:'Recebíveis',value:s.receivables,color:'#6E9DE8'}];
 const liabilities=[{name:'Dívidas',value:s.liabilities,color:'#E991A1'},{name:'Cartões',value:s.cardLiability,color:'#E8B06D'},{name:'Pagamentos empresariais',value:s.payables,color:'#947FED'}];
 const budgetData=(d.budgets||[]).filter((b:AnyRow)=>b.period===d.period);
 const activeSubs=d.subscriptions?.filter((a:AnyRow)=>a.status==='active')||[];
 const annualSubCost=activeSubs.reduce((sum:number,item:AnyRow)=>sum+Number(item.amount_cents)*(item.cadence==='weekly'?52:item.cadence==='yearly'?1:12),0);
 const cashFlowPanel=<Panel title="Fluxo financeiro por competência" subtitle="Receitas e despesas por mês · incluindo compras no cartão"><CashFlowChart data={last} mode="bar"/></Panel>;
 const categoryPanel=<Panel title="Distribuição das despesas" subtitle="Onde você mais gastou no período atual"><CategoryChart data={spent}/></Panel>;
 const monthlyOverview=<Panel title="Evolução do resultado" subtitle="Saldo das receitas menos despesas reconhecidas"><CashFlowChart data={last}/></Panel>;
 const upcoming=<Panel title="Próximos compromissos" subtitle="Vencimentos e renovações em até 60 dias" action={<button onClick={()=>onNavigate('business')} className="link">Ver todos <ChevronRight size={14}/></button>}><div className="list-simple upcoming">{d.upcoming?.length?d.upcoming.slice(0,7).map((u:AnyRow,i:number)=><div key={i}><span><CalendarClock size={16}/>{u.label||u.kind} · {String(u.due_on).slice(0,10).split('-').reverse().join('/')}</span><b>{money(u.amount_cents)}</b></div>):<div className="muted-padding">Nenhum vencimento registrado no período.</div>}</div></Panel>;
 if(report==='executive')return <>
  <div className="hero-callout"><div><span className="hero-tag"><Sparkles size={15}/> CONTROLE E INTELIGÊNCIA</span><h2>Decisões melhores começam<br/>com uma visão completa.</h2><p>Consolide seu dia a dia, identifique tendências e acompanhe a evolução do que importa.</p><button onClick={onAdd} className="btn hero-button"><Plus size={16}/> Registrar movimentação</button></div><div className="hero-ring"><span>SEU RESULTADO MENSAL</span><strong>{money(s.monthlyResult)}</strong><small>Taxa de poupança: {pct(s.savingsRate)}</small></div></div>
  {Summary}<div className="grid-2 wide-first">{monthlyOverview}{categoryPanel}</div><div className="grid-2">{cashFlowPanel}<Panel title="Sinais e oportunidades" subtitle="Regras transparentes baseadas nos dados disponíveis">{insightList}</Panel></div>
  <div className="grid-2">{upcoming}<Panel title="Movimentações recentes" subtitle="Registros financeiros mais recentes" action={<button className="link" onClick={()=>onNavigate('transactions')}>Ver tudo <ChevronRight size={14}/></button>}><div className="list-simple recent">{d.activity?.length?d.activity.slice(0,7).map((t:AnyRow,i:number)=><div key={i}><span><span className={`transaction-icon ${t.kind}`}>{t.kind==='income'?<ArrowDownLeft size={16}/>:t.kind==='transfer'?<ArrowLeftRight size={16}/>:<ArrowUpRight size={16}/>}</span><span>{t.description}<small>{String(t.occurred_on).slice(0,10)}</small></span></span><b className={t.kind==='income'?'positive':'negative'}>{t.kind==='income'?'+':'−'}{money(t.amount_cents)}</b></div>):<div className="muted-padding">Nenhum lançamento ainda.</div>}</div></Panel></div>
 </>;
 if(report==='cashflow')return <>{Summary}<div className="grid-2 wide-first">{cashFlowPanel}{monthlyOverview}</div><Panel title="Comparativo mensal" subtitle="Resultado por competência, excluindo transferências internas"><DataSummaryTable rows={last.map((a:AnyRow)=>({Período:a.month,Receitas:money(a.income),Despesas:money(a.expenses),Resultado:money(a.result)}))}/></Panel></>;
 if(report==='expenses')return <><div className="mini-metrics"><Metric label="Despesas" value={money(s.monthlyExpense)} icon={ArrowUpRight}/><Metric label="Variação mensal" value={prior.expenses?trend(s.monthlyExpense,prior.expenses):'—'} icon={Activity}/><Metric label="Maior categoria" value={spent[0]?.name||'—'} icon={Layers}/></div><div className="grid-2">{categoryPanel}<Panel title="Ranking de despesas" subtitle="Categorias ordenadas por valor"><HorizontalBars data={spent}/></Panel></div>{cashFlowPanel}</>;
 if(report==='budget')return <><div className="mini-metrics"><Metric label="Planejado" value={money(budgetData.reduce((a:number,b:AnyRow)=>a+Number(b.limit_cents),0))} icon={Target}/><Metric label="Consumido nos orçamentos" value={money(budgetData.reduce((a:number,b:AnyRow)=>a+Number(b.used),0))} icon={BarChart3}/><Metric label="Categorias acima do limite" value={String(budgetData.filter((b:AnyRow)=>b.used>b.limit_cents).length)} icon={AlertTriangle}/></div><Panel title="Aderência ao planejamento" subtitle="Comprometimento por categoria"><div className="budget-rows">{budgetData.map((b:AnyRow)=><div className="budget-row" key={b.id}><div><b>{b.category}</b><small>{money(b.used)} de {money(b.limit_cents)}</small></div><div className="bar"><span className={b.remaining<0?'over':''} style={{width:`${Math.min(100,b.limit_cents?b.used/b.limit_cents*100:100)}%`}}/></div><strong>{b.limit_cents?pct(b.used/b.limit_cents*100):'—'}</strong></div>)}{!budgetData.length&&<Empty action={()=>onNavigate('budgets')}/>}</div></Panel></>;
 if(report==='cards')return <><div className="mini-metrics"><Metric label="Cartões ativos" value={String(cards.length)} icon={CreditCard}/><Metric label="Saldo pendente" value={money(s.cardLiability)} icon={WalletCards}/><Metric label="Limites totais" value={money(cards.reduce((a:number,c:AnyRow)=>a+Number(c.limit_cents),0))} icon={Target}/></div><div className="grid-2">{cards.map((c:AnyRow)=><Panel key={c.id} title={c.name} subtitle="Visão consolidada do limite e pagamentos">{monthlyCard(c)}</Panel>)}{!cards.length&&<Panel title="Cartões" subtitle="Sem cartões cadastrados"><Empty action={()=>onNavigate('cards')}/></Panel>}</div></>;
 if(report==='investment')return <><div className="mini-metrics"><Metric label="Valor de mercado estimado" value={money(s.invested)} icon={TrendingUp}/><Metric label="Custo de aquisição remanescente" value={money(positions.reduce((a:number,p:AnyRow)=>a+p.cost,0))} icon={Wallet}/><Metric label="Resultado não realizado" value={money(positions.reduce((a:number,p:AnyRow)=>a+p.unrealized,0))} icon={Activity}/></div><div className="grid-2"><Panel title="Distribuição da carteira" subtitle="Preços manuais ou último preço negociado"><CategoryChart data={allocation} centerLabel="Carteira investida"/></Panel><Panel title="Exposição por ativo" subtitle="Valor consolidado por posição"><HorizontalBars data={allocation}/></Panel></div><Panel title="Posições e performance" subtitle="Valores de mercado são estimativas e dependem das cotações cadastradas"><DataSummaryTable rows={positions.map((p:AnyRow)=>({Ativo:p.symbol||p.asset_name,Classe:p.asset_class,Quantidade:p.quantity.toFixed(6),Custo:money(p.cost),Mercado:money(p.market),'P&L':money(p.unrealized)}))}/></Panel></>;
 if(report==='wealth')return <><div className="mini-metrics"><Metric label="Ativos financeiros" value={money(s.cash+s.invested)} icon={Wallet}/><Metric label="Bens avaliados" value={money(s.tangible)} icon={Landmark}/><Metric label="Patrimônio líquido" value={money(s.netWorth)} icon={Layers}/></div><div className="grid-2"><Panel title="Composição patrimonial" subtitle="Ativos e recebíveis"><CategoryChart data={financialStack.filter(x=>x.value>0)} centerLabel="Ativos e bens"/></Panel><Panel title="Ativos por classe" subtitle="Decomposição do valor consolidado"><HorizontalBars data={financialStack}/></Panel></div></>;
 if(report==='liabilities')return <><div className="mini-metrics"><Metric label="Passivos totais" value={money(s.liabilities+s.cardLiability+s.payables)} icon={WalletCards}/><Metric label="Dívidas contratadas" value={money(s.liabilities)} icon={Landmark}/><Metric label="Cartões e faturas" value={money(s.cardLiability)} icon={CreditCard}/></div><div className="grid-2"><Panel title="Composição das obrigações" subtitle="Contratos, crédito e fornecedores"><CategoryChart data={liabilities.filter(x=>x.value>0)} centerLabel="Obrigações"/></Panel><Panel title="Dívidas em aberto" subtitle="Saldos de principal"><HorizontalBars data={debts.map((x:AnyRow)=>({name:x.name,value:Number(x.remaining_cents)}))}/></Panel></div>{upcoming}</>;
 if(report==='business')return <><div className="mini-metrics"><Metric label="Contas a receber" value={money(s.receivables)} icon={ArrowDownLeft}/><Metric label="Contas a pagar" value={money(s.payables)} icon={ArrowUpRight}/><Metric label="Documentos abertos" value={String(s.openInvoices)} icon={FileClock}/></div><div className="grid-2"><Panel title="Contas a receber x pagar" subtitle="Valores em aberto"><HorizontalBars data={[{name:'A receber',value:s.receivables,color:'#4db5a5'},{name:'A pagar',value:s.payables,color:'#ea909d'}]}/></Panel><Panel title="Documentos por situação" subtitle="Distribuição de obrigações"><CategoryChart data={[{name:'A receber',value:s.receivables,color:'#4db5a5'},{name:'A pagar',value:s.payables,color:'#ea909d'}].filter(x=>x.value>0)} centerLabel="Valores em aberto"/></Panel></div>{upcoming}</>;
 if(report==='forecast')return <><div className="notice warning"><AlertTriangle size={20}/><span>Projeção indicativa calculada pela média dos últimos registros (até seis meses), sem cenários macroeconômicos, sazonalidade ou garantia de resultado. Não representa aconselhamento financeiro.</span></div><div className="mini-metrics"><Metric label="Resultado médio" value={money(forecast[0]?.result||0)} icon={TrendingUp}/><Metric label="Receita mensal esperada" value={money(forecast[0]?.income||0)} icon={ArrowDownLeft}/><Metric label="Despesa mensal esperada" value={money(forecast[0]?.expenses||0)} icon={ArrowUpRight}/></div><Panel title="Cenário base · próximos seis meses" subtitle="Previsão determinística · médias históricas"><CashFlowChart data={future} mode="line"/></Panel><Panel title="Fluxo projetado" subtitle="Visão mensal sem movimentos futuros externos"><DataSummaryTable rows={forecast.map((x:AnyRow)=>({Período:x.month,Receita:money(x.income),Despesa:money(x.expenses),Resultado:money(x.result)}))}/></Panel></>;
 if(report==='opportunities')return <><div className="mini-metrics"><Metric label="Pipeline bruto" value={money(d.opportunities?.reduce((a:number,o:AnyRow)=>a+Number(o.expected_cents),0))} icon={BriefcaseBusiness}/><Metric label="Pipeline ponderado" value={money(s.weightedPipeline)} icon={Target}/><Metric label="Receita disponível" value={money(Math.max(0,s.monthlyResult))} icon={Sparkles}/></div><div className="grid-2"><Panel title="Oportunidades por estágio" subtitle="Total estimado de negócios"><HorizontalBars data={Object.entries((d.opportunities||[]).reduce((acc:Record<string,number>,x:AnyRow)=>{acc[x.stage]=(acc[x.stage]||0)+Number(x.expected_cents);return acc;},{})).map(([name,value])=>({name,value:value as number}))}/></Panel><Panel title="Sinais de otimização" subtitle="Possíveis ações a partir de indicadores">{insightList}</Panel></div></>;
 if(report==='insights')return <><div className="mini-metrics"><Metric label="Insights ativos" value={String(d.insights?.length||0)} icon={Sparkles}/><Metric label="Compromissos recorrentes / ano" value={money(annualSubCost)} icon={CalendarClock}/><Metric label="Potencial comercial ponderado" value={money(s.weightedPipeline)} icon={BriefcaseBusiness}/></div><div className="grid-2"><Panel title="Central de insights" subtitle="Alertas gerados por regras observáveis">{insightList}</Panel><Panel title="Oportunidades de economia" subtitle="Compromissos recorrentes e contratos"><div className="list-simple">{activeSubs.slice(0,12).map((x:AnyRow)=><div key={x.id}><span>{x.name} · {x.cadence}</span><b>{money(x.amount_cents)}</b></div>)}{!activeSubs.length&&<div className="muted-padding">Cadastre assinaturas para identificar compromissos recorrentes.</div>}</div></Panel></div></>;
 return null;
}
function DataSummaryTable({rows}:{rows:AnyRow[]}){if(!rows?.length)return <ChartEmpty/>;return <div className="table-scroll summary-table"><table><thead><tr>{Object.keys(rows[0]).map(k=><th key={k}>{k}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i}>{Object.values(r).map((v,j)=><td key={j}>{String(v)}</td>)}</tr>)}</tbody></table></div>;}
function AuthScreen({mode,error,onSubmit}:{mode:'login'|'setup',error:string,onSubmit:(values:Record<string,string>)=>void}){
 const [values,setValues]=useState<Record<string,string>>({}),[submitting,setSubmitting]=useState(false);
 const submit=async(e:React.FormEvent)=>{e.preventDefault();setSubmitting(true);await onSubmit(values);setSubmitting(false);};
 return <div className="auth-page"><div className="auth-ambient auth-ambient-one"/><div className="auth-ambient auth-ambient-two"/><div className="auth-box"><div className="auth-logo"><span><Layers size={25}/></span>finance<b>hub</b></div><div className="auth-label"><ShieldCheck size={15}/> 100% SELF-HOSTED · LOCAL-FIRST</div><h1>{mode==='setup'?'Seu espaço financeiro começa aqui.':'Bem-vindo de volta.'}</h1><p>{mode==='setup'?'Configure a conta proprietária. O código de instalação foi gerado pelo script init.ps1.':'Entre na sua central privada de finanças, investimentos e negócios.'}</p><form onSubmit={submit}>
  {mode==='setup'&&<><label>Nome completo<input required value={values.name||''} onChange={e=>setValues({...values,name:e.target.value})} placeholder="Seu nome"/></label><label>Código de instalação<input required value={values.code||''} onChange={e=>setValues({...values,code:e.target.value})} placeholder="Código gerado no PowerShell" autoComplete="off"/></label></>}
  <label>E-mail<input type="email" required value={values.email||''} onChange={e=>setValues({...values,email:e.target.value})} placeholder="voce@exemplo.com" autoComplete="username"/></label>
  <label>Senha<input type="password" required minLength={mode==='setup'?8:1} value={values.password||''} onChange={e=>setValues({...values,password:e.target.value})} placeholder={mode==='setup'?'Mínimo de 8 caracteres':'Sua senha'} autoComplete={mode==='setup'?'new-password':'current-password'}/></label>
  {mode==='setup'&&<p className="password-advice">Mínimo de 8 caracteres para uso exclusivamente local. Para proteger dados financeiros, recomendamos uma frase-senha de 15 caracteres ou mais. Não reutilize senhas.</p>}
  {error&&<div className="auth-error"><AlertTriangle size={16}/>{error}</div>}
  <button className="btn btn-primary auth-submit" disabled={submitting}>{submitting?'Processando...':mode==='setup'?'Criar ambiente seguro':'Acessar o Finance Hub'}<ChevronRight size={17}/></button>
 </form><div className="auth-footer"><LockKeyhole size={17}/> Transmissão local · Sessões protegidas · AES-256-GCM</div></div><div className="auth-side"><div className="auth-side-top"><span className="side-pill"><Activity size={16}/> SEU CONTROLE, SEUS DADOS</span><h2>Mais inteligência.<br/>Menos incerteza.</h2><p>Um ecossistema completo para finanças pessoais, gestão familiar, patrimônio, investimentos e análise empresarial.</p></div><div className="auth-side-card"><div><span>PATRIMÔNIO</span><h3>Uma visão que conecta tudo.</h3><small>Contas · Investimentos · Negócios · Orçamentos</small></div><div className="fake-chart"><span style={{height:'43%'}}/><span style={{height:'66%'}}/><span style={{height:'49%'}}/><span style={{height:'78%'}}/><span style={{height:'70%'}}/><span style={{height:'95%'}}/></div></div></div></div>;
}
function DataModal({entity,row,fields:input,references,categories,onSave,onClose,error}:{entity:string,row?:AnyRow,fields:Field[],references:Record<string,AnyRow[]>,categories:AnyRow[],onSave:(v:AnyRow)=>Promise<void>,onClose:()=>void,error:string}){
 const fields=input;
 const defaults=Object.fromEntries(fields.map(f=>{
  const fromRow=row?.[f.key]??(f.key.endsWith('_enc')?row?.[f.key.slice(0,-4)]:undefined);
  const value=fromRow??f.default??(f.type==='date'?today():f.type==='money'?0:f.type==='checkbox'?false:'');
  return [f.key,f.type==='money'?(Number(value)/100).toFixed(2):typeof value==='string'&&f.type==='date'?value.slice(0,10):value];
 }));
 const [state,setState]=useState<AnyRow>({...defaults,...(entity==='invoice_settle'&&row?.id?{id:row.id}:{})}),[working,setWorking]=useState(false);
 const options=(f:Field):[string,string][]=>{
  if(f.type==='select')return f.options||[];
  if(f.type==='category'||f.type==='category-expense')return categories.filter(c=>f.type==='category'||c.kind==='expense').map(c=>[c.id,`${c.name} (${c.kind==='income'?'receita':'despesa'})`]);
  const typeToEntity:Record<string,string>={account:'accounts',card:'cards',asset:'assets',contact:'contacts',debt:'debts',invoice:'invoices'};
  return (references[typeToEntity[f.type||'']]||[]).map(x=>[x.id,x.name||x.symbol||x.number||x.id]);
 };
 const submit=async(e:React.FormEvent)=>{e.preventDefault();setWorking(true);try{
   const b:AnyRow={};for(const f of fields){const val=state[f.key];if(!f.required&&(val===''||val===null||val===undefined))continue;
    b[f.key]=f.type==='money'?exactCents(val):['number'].includes(f.type||'')?Number(val):f.type==='checkbox'?!!val:val;
   }await onSave(b);
  }finally{setWorking(false);}};
 const isImport=entity==='import';
 return <div className="modal-backdrop" onMouseDown={onClose}><div className="modal" onMouseDown={e=>e.stopPropagation()}><div className="modal-top"><div><span className="modal-kicker">FINANCE HUB · {row?'EDITAR':'NOVO REGISTRO'}</span><h2>{entity==='invoice_settle'?'Quitar documento':entity==='import'?'Importar extrato CSV':`${row?'Editar':'Adicionar'} ${enName[entity]||entity}`}</h2><p>{isImport?'CSV: date,description,amount,kind (valores positivos). OFX: blocos STMTTRN. Duplicatas serão ignoradas.':'Os dados serão registrados no seu espaço com controle de acesso e auditoria.'}</p></div><button className="icon-btn" onClick={onClose} aria-label="Fechar"><X size={20}/></button></div>
  <form onSubmit={submit}><div className="modal-fields">{fields.map(f=><label className={f.type==='textarea'?'wide':''} key={f.key}><span>{f.label}{f.required!==false?' *':''}</span>{f.type==='checkbox'?<div className="check-row"><input type="checkbox" checked={Boolean(state[f.key])} onChange={e=>setState({...state,[f.key]:e.target.checked})}/><small>{state[f.key]?'Habilitado':'Desabilitado'}</small></div>:f.type==='textarea'?<><input className="file-input" type="file" accept=".csv,.ofx,text/csv,application/x-ofx" onChange={async e=>{const file=e.target.files?.[0];if(file){if(file.size>1000000){alert('Arquivo acima do limite de 1 MB.');return;}const contents=await file.text();setState(old=>({...old,[f.key]:contents}));}}}/><textarea rows={9} required={f.required!==false} placeholder={'date,description,amount,kind\n2026-10-01,Salário,9000.00,income\n2026-10-02,Mercado,240.50,expense'} value={state[f.key]??''} onChange={e=>setState({...state,[f.key]:e.target.value})}/></>:['select','account','card','category','category-expense','asset','contact','debt','invoice'].includes(f.type||'')?<select required={f.required!==false} value={state[f.key]??''} onChange={e=>setState({...state,[f.key]:e.target.value})}><option value="">Selecione...</option>{options(f).map(([v,label])=><option key={v} value={v}>{label}</option>)}</select>:<input required={f.required!==false} type={f.type==='money'||f.type==='number'?'number':f.type||'text'} step={f.type==='money'?'0.01':f.type==='number'?'any':undefined} min={f.type==='money'?'0':undefined} value={state[f.key]??''} onChange={e=>setState({...state,[f.key]:e.target.value})}/>}</label>)}</div>
  {entity==='trades'&&<div className="form-tip"><Activity size={16}/> Em compras e vendas, o valor é calculado por quantidade × preço. Para dividendos e taxas, use o campo “Valor para dividendos e taxas”.</div>}
  {entity==='schedules'&&<div className="form-tip"><AlertTriangle size={16}/> Marcar “Permitir lançamento automático” autoriza o worker a registrar movimentações de acordo com o calendário, sem confirmação adicional.</div>}
  {error&&<div className="auth-error"><AlertTriangle size={16}/>{error}</div>}
  <div className="modal-footer"><button type="button" className="btn btn-secondary" onClick={onClose}>Cancelar</button><button type="submit" disabled={working} className="btn btn-primary">{working?'Salvando...':'Salvar alterações'} <Check size={16}/></button></div></form>
 </div></div>;
}
